import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, PointLight, AmbientLight } = ctx.THREE;

  const group = new Group();
  const primitives = [];
  const timelines = [];

  // 1. PALETTE & COLORS
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 2. STAGE BACKDROP (Designed-for-dark backdrop)
  const backdropGeo = new PlaneGeometry(8, 6);
  const backdropMat = new MeshBasicNodeMaterial({ depthWrite: false });
  // Vertical gradient from ink to surface
  const gradNode = mix(
    color(colors.surface),
    color(colors.ink),
    uv().y
  );
  backdropMat.colorNode = gradNode;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.0;
  group.add(backdrop);

  // Contact shadow plane underneath the main card
  const shadowGeo = new PlaneGeometry(3.5, 0.8);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
    depthWrite: false
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -1.0, 0.1);
  shadow.rotation.x = -Math.PI / 2;
  group.add(shadow);

  // 3. ATELIER MACHINED CARD
  const cardGeo = new BoxGeometry(3.2, 1.9, 0.15);
  const cardMat = new MeshPhysicalNodeMaterial({
    color: colors.surface,
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3
  });
  const card = new Mesh(cardGeo, cardMat);
  card.position.set(0, 0, 0.2);
  group.add(card);

  // Frame Border (Sleek red accent border highlights)
  const borderGeo = new BoxGeometry(3.24, 1.94, 0.05);
  const borderMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    roughness: 0.2,
    metalness: 0.8
  });
  const border = new Mesh(borderGeo, borderMat);
  border.position.set(0, 0, 0.15);
  group.add(border);

  // 4. LIGHTING SETUP
  const rimLight = new PointLight(colors.accent, 1.4, 6);
  rimLight.position.set(1.5, 1.0, 1.2);
  group.add(rimLight);

  const fillLight = new PointLight(colors.paper, 0.8, 8);
  fillLight.position.set(-2.0, -1.0, 1.5);
  group.add(fillLight);

  // 5. ASSET LOADING (Machined gear mesh)
  const gearGroup = new Group();
  gearGroup.position.set(-0.8, 0, 0.4);
  gearGroup.scale.set(1.4, 1.4, 1.4);
  group.add(gearGroup);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const model = gltf.scene;
      model.traverse((child) => {
        if (child.isMesh) {
          child.material = new MeshPhysicalNodeMaterial({
            color: colors.paper,
            roughness: 0.25,
            metalness: 0.85,
            clearcoat: 0.1
          });
        }
      });
      gearGroup.add(model);

      // Continuous subtle spin loop
      const spinTimeline = gsap.to(gearGroup.rotation, {
        z: Math.PI * 2,
        duration: 20,
        repeat: -1,
        ease: 'none'
      });
      timelines.push(spinTimeline);
    }).catch(err => console.error("Failed to load gear GLB", err));
  }

  // 6. TYPOGRAPHY & STAT TEXT CONTENT
  const textContainer = new Group();
  textContainer.position.set(0.4, 0, 0.35);
  group.add(textContainer);

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let valStr = "98%";
  let labelStr = "PRECISION";

  if (textItems.length > 0) {
    valStr = textItems[0].text;
    if (textItems[1]) labelStr = textItems[1].text;
  }

  // Large Value Display
  const valueText = ctx.fontAtlas.createText(valStr, {
    fontSize: 0.46,
    color: colors.paper,
    align: 'left'
  });
  valueText.position.set(0, 0.15, 0);
  textContainer.add(valueText);

  // Mini label
  const labelText = ctx.fontAtlas.createText(labelStr.toUpperCase(), {
    fontSize: 0.11,
    color: colors.accent,
    align: 'left',
    letterSpacingPx: 12
  });
  labelText.position.set(0, -0.28, 0);
  textContainer.add(labelText);

  // 7. INTERACTION HANDLERS & ANIMATIONS
  const targetY = group.position.y;
  let hoverTimeline = null;

  group.userData.handlers = {
    onPointerOver: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(group.position, {
        y: targetY + 0.15,
        duration: 0.4,
        ease: 'power3.out'
      });
    },
    onPointerOut: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(group.position, {
        y: targetY,
        duration: 0.5,
        ease: 'power2.out'
      });
    },
    onClick: () => {
      // Settle-down physical click effect
      gsap.to(group.scale, {
        x: 0.96,
        y: 0.96,
        z: 0.96,
        duration: 0.1,
        yoyo: true,
        repeat: 1,
        ease: 'power2.inOut'
      });

      ctx.emit('hub-collection.select', { 
        id: config.id ?? 'stat-tile',
        capability: 'shopify.catalog'
      });
    }
  };

  // 8. ENTRANCE STAGES (Weighted Settle)
  group.position.y = targetY - 0.4;
  group.scale.set(0.9, 0.9, 0.9);

  const entranceTl = gsap.timeline();
  entranceTl.to(group.position, {
    y: targetY,
    duration: 0.9,
    ease: 'power4.out'
  }).to(group.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.8,
    ease: 'back.out(1.4)'
  }, '-=0.7');
  timelines.push(entranceTl);

  // 9. APPLY CINEMATIC PRIMITIVES
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives[primitive.name]) {
        const primInstance = ctx.primitives[primitive.name](group, primitive.params);
        if (primInstance) {
          primitives.push(primInstance);
        }
      }
    });
  }

  // 10. CLEANUP METHOD
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    if (hoverTimeline) hoverTimeline.kill();
    primitives.forEach(prim => {
      if (typeof prim.cleanup === 'function') prim.cleanup();
    });

    // Dispose geometry/materials
    backdropGeo.dispose();
    backdropMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    borderGeo.dispose();
    borderMat.dispose();
  };

  return group;
}
